actionArguments.expression:
try {
  const response = await http.put("/api/services/app/Customer/UpdateMyProfile", {
    firstName: data.firstName,
    lastName: data.lastName,
    emailAddress: data.emailAddress,
    mobileNumber: data.mobileNumber
  });
  form.setFieldsValue(response.data.result);
  message.success("Profile saved");
} catch (e) {
  message.error(e?.response?.data?.error?.message ?? "Could not save your profile");
}

formSettings.onBeforeDataLoad:
try {
  const response = await http.get("/api/services/app/Customer/GetProfile");
  form.setFieldsValue(response.data.result);
} catch (e) {
  message.error(e?.response?.data?.error?.message ?? "Could not load your profile");
}
